package com.lianxibu.site.controller.articles;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.service.articles.ArticlesService;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.identity.IdentityService.Actor;
import java.time.Instant;
import java.util.List;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class ArticleEntityControllerTest {
 private final Actor user=new Actor("fictional-user","user");private ArticlesService service;private MockMvc mvc;
 private final ArticlesService.Article article=new ArticlesService.Article("fictional-article","Fictional article",null,"fictional-source","Fictional source","https://example.invalid/story",null,Instant.parse("2026-01-09T00:00:00Z"),null,null,"unavailable",1,null);
 @BeforeEach @SuppressWarnings("unchecked") void setup(){var identity=mock(IdentityService.class);service=mock(ArticlesService.class);ObjectProvider<IdentityService> auth=mock(ObjectProvider.class);ObjectProvider<ArticlesService> provider=mock(ObjectProvider.class);when(auth.getIfAvailable()).thenReturn(identity);when(provider.getIfAvailable()).thenReturn(service);when(identity.authenticate("fictional-session")).thenReturn(user);mvc=MockMvcBuilders.standaloneSetup(new ArticlesController(auth,provider)).build();when(service.article(user,"fictional-article")).thenReturn(article);}
 @Test void defaultShapePreservedAndExplicitOptInReturnsSafeNullableSummary()throws Exception{var summary=new ArticlesService.EntitySummary("fictional-entity","news_tech",Instant.parse("2026-01-01T00:00:00Z"),null,null,null,null,null,4);var row=new ArticlesService.ArticleWithEntity(article,summary);when(service.articleWithEntity(user,"fictional-article")).thenReturn(row);when(service.listArticlesWithEntity(user,null,null,null,1,20)).thenReturn(new ArticlesService.ArticleEntityPage(List.of(row),1,20,1));mvc.perform(get(path()).cookie(cookie())).andExpect(status().isOk()).andExpect(jsonPath("$.data.entity_summary").doesNotExist());mvc.perform(get(path()).cookie(cookie()).param("include_entity","false")).andExpect(status().isOk()).andExpect(jsonPath("$.data.entity_summary").doesNotExist());mvc.perform(get(path()).cookie(cookie()).param("include_entity","true")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.entity_summary.id").value("fictional-entity")).andExpect(jsonPath("$.data.entity_summary.first_recorded_at").value("2026-01-01T00:00:00.000000Z")).andExpect(jsonPath("$.data.entity_summary.occurrence_count").value(org.hamcrest.Matchers.nullValue())).andExpect(jsonPath("$.data.entity_summary.raw_json").doesNotExist());mvc.perform(get("/private/articles").cookie(cookie()).param("include_entity","true")).andExpect(status().isOk()).andExpect(jsonPath("$.data.items[0].entity_summary.category").value("news_tech"));when(service.articleWithEntity(user,"fictional-article")).thenReturn(new ArticlesService.ArticleWithEntity(article,null));mvc.perform(get(path()).cookie(cookie()).param("include_entity","true")).andExpect(status().isOk()).andExpect(jsonPath("$.data.entity_summary").value(org.hamcrest.Matchers.nullValue()));}
 @Test void authenticationAndClosedBooleanQueryPrecedeMetadataReads()throws Exception{mvc.perform(get(path()).param("include_entity","true")).andExpect(status().isUnauthorized());mvc.perform(get(path()).cookie(cookie()).param("include_entity","true","false")).andExpect(status().isBadRequest());mvc.perform(get(path()).cookie(cookie()).param("include_entity","yes")).andExpect(status().isUnprocessableEntity());mvc.perform(get(path()).cookie(cookie()).param("page","1")).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void unavailableOrMalformedSummaryUsesGeneric503InsteadOfInventedAssociation()throws Exception{when(service.articleWithEntity(user,"fictional-article")).thenThrow(new IllegalStateException("Fictional private storage detail"));mvc.perform(get(path()).cookie(cookie()).param("include_entity","true")).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1")).andExpect(jsonPath("$.error.message").value("article service unavailable"));var wrong=new ArticlesService.EntitySummary("fictional-entity","model",null,null,null,null,null,null,0);doReturn(new ArticlesService.ArticleWithEntity(article,wrong)).when(service).articleWithEntity(user,"fictional-article");mvc.perform(get(path()).cookie(cookie()).param("include_entity","true")).andExpect(status().isServiceUnavailable());}
 private static String path(){return "/private/articles/fictional-article";}
 private static jakarta.servlet.http.Cookie cookie(){return new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session");}
}
